import requests
for pmid in ['25092099','25487489','32253016','31704043']:
 r=requests.get(f'https://www.ebi.ac.uk/europepmc/webservices/rest/search',params={'query':f'EXT_ID:{pmid}','format':'json','pageSize':1}).json()
 xs=r.get('resultList',{}).get('result',[])
 print('\nPMID',pmid)
 if xs:
  x=xs[0]; print(x.get('title')); print(x.get('abstractText','(no abstract available)'))
 else: print('No record')
